```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let urls = match state_read::get("urls") {
            Some(raw) => raw
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect::<Vec<String>>(),
            None => Vec::new(),
        };
        SubscriptionList { urls }
    }
}

export!(Node);
